#pragma once
// The UI Gallery's list: every component, style, theme, icon and screen in one searchable index, plus the counts the catalogue prints.
// The editor's UI Gallery window (editor/UIGalleryWindow.cpp) draws this list; the search and filter rules live here so
// tests/test_ui_library4.cpp can check them without a window. Counting rules are in docs/ui_catalogue.md (generated by scripts/gen_ui_catalogue.py).
#include "okay/Scene/UIScreens.hpp"
#include "okay/Scene/UIStyleLib.hpp"
#include "okay/UI/UIIcons.hpp"
#include <string>
#include <vector>

namespace okay { namespace UIGalleryIndex {

enum Kind { kComponent = 1, kStyle = 2, kTheme = 4, kIcon = 8, kScreen = 16, kAll = 31 };
inline const char* KindName(int k) {
    switch (k) { case kComponent: return "Component"; case kStyle: return "Style"; case kTheme: return "Theme"; case kIcon: return "Icon"; case kScreen: return "Screen"; default: return "?"; }
}

struct Entry {
    int kind = kComponent;
    std::string id, name, category, tags, desc;
    std::string menu;      // components: the GameObject > UI id that adds it ("" when added another way)
    int variants = 1;      // screens: layout variants
};

inline std::vector<Entry> Build() {
    std::vector<Entry> v;
    for (const auto& s : uilib::ParseData(uilib::EmbeddedData("ui_components"))) {
        if (s.kind != "component") continue;
        Entry e; e.kind = kComponent; e.id = s.name; e.name = s.name; e.category = s.Str("category"); e.tags = s.Str("tags"); e.desc = s.Str("desc"); e.menu = s.Str("menu");
        v.push_back(std::move(e));
    }
    for (const auto& s : UIStyleLib::Styles().styles) {
        Entry e; e.kind = kStyle; e.id = s.name; e.name = s.name; e.category = s.Str("family");
        e.tags = s.Str("shape") + "," + s.Str("fill") + "," + s.Str("border") + "," + s.Str("effect"); e.desc = s.Str("desc", "Shape " + s.Str("shape") + ", fill " + s.Str("fill") + ", border " + s.Str("border") + ", effect " + s.Str("effect") + ".");
        v.push_back(std::move(e));
    }
    for (const auto& t : UIStyleLib::Themes()) {
        Entry e; e.kind = kTheme; e.id = t.name; e.name = t.name; e.category = t.mode; e.tags = t.tags; e.desc = (t.builtin ? "Built-in theme. " : "Theme from data. ") + std::string("Switch with ui_set_theme(\"") + t.name + "\").";
        v.push_back(std::move(e));
    }
    for (const uilib::IconDef& d : uilib::Icons().icons) {
        Entry e; e.kind = kIcon; e.id = "icon:" + d.name; e.name = d.name; e.category = d.category; e.tags = d.tags; e.desc = "Use it as \"icon:" + d.name + "\" in a picture or a button's icon.";
        v.push_back(std::move(e));
    }
    for (const UIScreens::Def& d : UIScreens::Screens()) {
        Entry e; e.kind = kScreen; e.id = d.id; e.name = d.name; e.desc = d.desc; e.variants = UIScreens::VariantCount(d);
        for (const UIScreens::Section& s : UIScreens::Sections()) if (s.id == d.section) e.category = s.name;
        for (std::size_t i = 0; i < d.tags.size(); ++i) e.tags += (i ? "," : "") + d.tags[i];
        v.push_back(std::move(e));
    }
    return v;
}
inline const std::vector<Entry>& Index() { static const std::vector<Entry> v = Build(); return v; }

struct Query {
    std::string text;          // every word must appear in the name, category, tags or description (any case)
    int kinds = kAll;          // which kinds to show
    std::string category;      // exact category / section / family / theme mode ("" = any)
    std::string tag;           // one tag that must be in the tag list ("" = any)
};
inline std::string Lower(std::string s) { for (char& c : s) c = (char)std::tolower((unsigned char)c); return s; }

inline std::vector<const Entry*> Search(const Query& q) {
    std::vector<std::string> words;
    std::string cur;
    for (char c : q.text + " ") { if (c == ' ') { if (!cur.empty()) words.push_back(cur); cur.clear(); } else cur.push_back((char)std::tolower((unsigned char)c)); }
    const std::string wantTag = Lower(q.tag);
    std::vector<const Entry*> out;
    for (const Entry& e : Index()) {
        if (!(q.kinds & e.kind)) continue;
        if (!q.category.empty() && e.category != q.category) continue;
        if (!wantTag.empty()) {
            bool has = false;
            for (const std::string& t : uilib::Split(Lower(e.tags), ',')) if (t == wantTag) { has = true; break; }
            if (!has) continue;
        }
        if (!words.empty()) {
            const std::string hay = Lower(e.name + " " + e.category + " " + e.tags + " " + e.desc);
            bool ok = true;
            for (const std::string& w : words) if (hay.find(w) == std::string::npos) { ok = false; break; }
            if (!ok) continue;
        }
        out.push_back(&e);
    }
    return out;
}

/// The categories present for a set of kinds, in first-seen order (for the filter drop-down).
inline std::vector<std::string> Categories(int kinds) {
    std::vector<std::string> v;
    for (const Entry& e : Index()) {
        if (!(kinds & e.kind) || e.category.empty()) continue;
        if (std::find(v.begin(), v.end(), e.category) == v.end()) v.push_back(e.category);
    }
    return v;
}

struct Counts {
    int components = 0, styles = 0, themes = 0, themesBuiltin = 0, icons = 0, iconsDrawn = 0, iconsDerived = 0, screens = 0, screensData = 0, screenVariants = 0;
    int shapes = 0, fills = 0, borders = 0, effects = 0, sizes = 0, densities = 0, stateLooks = 0;
    long long combinations = 0, optionCombinations = 0;
};
inline Counts Count() {
    Counts c;
    for (const Entry& e : Index()) {
        if (e.kind == kComponent) ++c.components;
        else if (e.kind == kStyle) ++c.styles;
        else if (e.kind == kTheme) ++c.themes;
        else if (e.kind == kIcon) ++c.icons;
        else if (e.kind == kScreen) { ++c.screens; c.screenVariants += e.variants; }
    }
    for (const auto& t : UIStyleLib::Themes()) if (t.builtin) ++c.themesBuiltin;
    for (const uilib::IconDef& d : uilib::Icons().icons) { if (d.baseName.empty()) ++c.iconsDrawn; else ++c.iconsDerived; }
    for (const UIScreens::Def& d : UIScreens::Screens()) if (d.native.empty()) ++c.screensData;
    namespace S = UIStyleLib;
    c.shapes = (int)S::AxisCount("shape"); c.fills = (int)S::AxisCount("fill"); c.borders = (int)S::AxisCount("border"); c.effects = (int)S::AxisCount("effect");
    c.sizes = (int)S::AxisCount("size"); c.densities = (int)S::AxisCount("density");
    c.stateLooks = (int)(S::AxisCount("hover") + S::AxisCount("press") + S::AxisCount("disabled") + S::AxisCount("focus"));
    c.combinations = (long long)S::CombinationCount();
    c.optionCombinations = c.combinations * c.sizes * c.densities;
    return c;
}

}} // namespace okay::UIGalleryIndex
